mapper.select:
SELECT a.id, a.alarm_id, a.type, a.device_id, a.spi, a.level, a.alarm_desc, a.eng_desc, a.state, a.s_time, a.e_time, a.c_time, a.s_option, a.e_option, a.c_option, a.c_user, a.parent, a.push_time, a.is_discharge, a.ext_info, a.receive_time, c.device_name, c.warehouse, c.device_type, c.location FROM wms_env_alarm a LEFT JOIN wms_env_device c ON c.device_id = a.device_id
AND a.device_id = #{query.deviceId}
AND JSON_UNQUOTE(JSON_EXTRACT(a.ext_info, '$.alarmType')) = #{query.alarmType}
AND a.ext_info::jsonb ->> 'alarmType' = #{query.alarmType}
AND a.state = #{query.state}
AND a.s_time >= #{query.beginTime}
AND a.s_time <= #{query.endTime}
ORDER BY a.s_time DESC
